<script setup lang="ts">import {computed,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useSessionStore} from '@ygh/web-shared';import {Bell,Box,ChatDotRound,Collection,Connection,Document,Goods,Grid,Key,Lock,Management,Menu,Message,Money,Operation,Reading,Setting,SwitchButton,User} from '@element-plus/icons-vue';const route=useRoute();const router=useRouter();const session=useSessionStore();const collapsed=ref(false);const title=computed(()=>String(route.meta.title||'运营后台'));const groups=[{name:'工作台',items:[{to:'/dashboard',label:'运营总览',icon:Grid}]},{name:'交易运营',items:[{to:'/products',label:'商品中心',icon:Goods},{to:'/inventory',label:'库存中心',icon:Box},{to:'/orders',label:'订单管理',icon:Document},{to:'/wallet',label:'钱包与流水',icon:Money}]},{name:'知识与成长',items:[{to:'/knowledge',label:'知识库治理',icon:Collection},{to:'/ai',label:'AI 客服治理',icon:ChatDotRound},{to:'/training',label:'培训运营',icon:Reading},{to:'/notifications',label:'通知与补偿',icon:Message}]},{name:'组织与系统',items:[{to:'/users',label:'用户与员工',icon:User},{to:'/roles',label:'角色与权限',icon:Key},{to:'/system',label:'系统配置',icon:Setting},{to:'/audit',label:'审计与安全',icon:Lock}]}];function logout(){session.clear();router.replace('/login')};</script>
